/* City Brush v35 — landmark intro cards, San Francisco Bay Area (info_bay)
   window.LM_INFO[key] = {k, y, a, h, fl, d, x}  — see lm31/BRIEF.md (data contract)
   Covers every key in lm31/kit/lm_bay.json (labelled keys: full entries; label:false keys: {p:parent})
   and the Bay sites: sfoairport, applepark, googleplex, googlebayview, stanforduniv, ucberkeley.
   Fields left out where a fact was not certain. */
Object.assign(window.LM_INFO = window.LM_INFO || {}, {

  /* ---------------- bridges ---------------- */
  baybridgew1: {k:{zh:"双悬索桥", en:"Twin suspension bridge"}, y:"1936", a:{zh:"查尔斯·H·珀塞尔（总工程师）", en:"Charles H. Purcell (chief engineer)"}, h:160,
    d:{zh:"海湾大桥西桥其实是两座首尾相接的悬索桥，在海湾中央共用一座混凝土锚碇，从旧金山林康山一直跨到耶尔巴布埃纳岛。它 1936 年通车，比金门大桥还早半年；桥面分上下两层，各走一个方向。2013 年起，桥索上数万盏 LED 灯组成了灯光艺术《海湾之光》。",
       en:"The west span is really two suspension bridges set end to end, sharing a concrete anchorage in the middle of the bay between Rincon Hill and Yerba Buena Island. It opened in November 1936, six months before the Golden Gate Bridge, with one deck for each direction. Since 2013 its cables have carried the LED artwork “The Bay Lights”."}},
  baybridgesf: {p:"baybridgew1"},
  baybridgeanch: {p:"baybridgew1"},
  baybridgew2: {p:"baybridgew1"},
  baybridgesas: {k:{zh:"自锚式悬索桥", en:"Self-anchored suspension bridge"}, y:"2013", a:{zh:"T.Y. 林国际、莫法特-尼科尔", en:"T.Y. Lin International, Moffatt & Nichol"}, h:160,
    d:{zh:"东桥连接耶尔巴布埃纳岛与奥克兰，2013 年通车，取代了在 1989 年洛马普列塔地震中上层桥面局部塌落的旧悬臂桁架桥。它的主跨是单塔自锚式悬索桥，为世界同类桥梁中最大的一座；之后是一段贴着浅水延伸到奥克兰的长长混凝土引桥。",
       en:"The east span links Yerba Buena Island with Oakland and opened in 2013. It replaced the old cantilever span, part of whose upper deck fell in the 1989 Loma Prieta earthquake. Its single-tower self-anchored suspension span is the largest of its kind in the world, followed by a long concrete viaduct, the Skyway, over shallow water to Oakland."}},
  baybridgeybi: {p:"baybridgesas"},
  baybridgesky: {p:"baybridgesas"},

  sanmateobridge: {k:{zh:"跨海湾大桥", en:"Bay crossing"}, y:"1967",
    d:{zh:"圣马特奥-海沃德大桥横跨海湾南部，西起福斯特城，东到海沃德，全长约 11 公里，是湾区最长的桥。现在的桥 1967 年通车，取代了 1929 年的老桥：西段抬高成钢梁通航段，东段是一条贴着水面的长栈桥。",
       en:"The San Mateo–Hayward Bridge crosses the southern bay from Foster City to Hayward. About 11 km long, it is the longest bridge in the Bay Area. The current bridge opened in 1967, replacing a 1929 crossing: a raised steel section lets ships pass in the west, and a long, low trestle runs east."}},
  sanmateobridge2: {k:{zh:"大桥通航高架段", en:"Bridge high-rise section"}, y:"1967",
    d:{zh:"这是圣马特奥-海沃德大桥西侧抬高的一段，钢箱梁把桥面高高托起，让船只从下方的主航道通过。开车经过时能明显感到桥面先爬升再下降，这里也是全桥视野最开阔的地方。",
       en:"This is the raised western section of the San Mateo–Hayward Bridge. Steel box girders lift the roadway high above the main shipping channel so that vessels can pass underneath. Drivers feel a long climb and descent here, and get the widest views of the bay from the top."}},
  sanmateobridge3: {k:{zh:"大桥栈桥段", en:"Bridge trestle"},
    d:{zh:"大桥东段是一条贴近水面、笔直延伸好几公里的混凝土栈桥，由成排的桩柱托着。后来在它旁边又加建了一条平行的栈桥来增加车道。从这里可以看到东湾岸边的浅滩、盐田和湿地。",
       en:"The eastern part of the bridge is a low concrete trestle that runs straight for several kilometres just above the water on rows of piles. A second, parallel trestle was later built beside it to add lanes. From here the shallows, salt ponds and marshes of the East Bay shore come into view."}},

  dumbartonbridge: {k:{zh:"跨海湾大桥", en:"Bay crossing"}, y:"1982",
    d:{zh:"邓巴顿大桥是旧金山湾最南端的跨湾桥梁，连接门洛帕克和纽瓦克、弗里蒙特一带。1927 年这里建成了第一座横跨旧金山湾的汽车桥；现在的桥 1982 年通车，中段抬高供船只通过，桥上还有自行车和步行道。",
       en:"The Dumbarton Bridge is the southernmost crossing of San Francisco Bay, linking Menlo Park with Newark and Fremont. The first road bridge across the bay was built here in 1927. The current bridge opened in 1982, with a raised central span for boats and a path for bikes and pedestrians."}},
  dumbartonbridge2: {k:{zh:"大桥引桥", en:"Bridge approach"}, y:"1982",
    d:{zh:"纽瓦克引桥是邓巴顿大桥东端上岸前的一段，低矮的混凝土梁段从盐田和湿地之间穿过。旁边就是唐·爱德华兹旧金山湾国家野生动物保护区，浅水里常能看到各种水鸟。",
       en:"The Newark approach carries the eastern end of the Dumbarton Bridge on low concrete spans between salt ponds and marshland. The Don Edwards San Francisco Bay National Wildlife Refuge lies alongside, and many kinds of shorebirds feed in the shallow water."}},

  rsrbridge: {k:{zh:"双层悬臂桁架桥", en:"Double-deck cantilever truss bridge"}, y:"1956",
    d:{zh:"里士满-圣拉斐尔大桥连接东湾的里士满与马林县，全长约 8.9 公里，1956 年通车。两段高耸的钢桁架通航孔之间桥面向下凹，远看起伏像过山车。2019 年，上层桥面开通了一条自行车和步行道。",
       en:"The Richmond–San Rafael Bridge links Richmond in the East Bay with Marin County. It is about 8.9 km long and opened in 1956. Between its two tall steel-truss shipping spans the deck dips down, giving it a rollercoaster profile. A bike and walking path opened on the upper deck in 2019."}},
  rsrbridge2: {k:{zh:"大桥桁架段", en:"Bridge truss spans"}, y:"1956",
    d:{zh:"主航道以西，一连串钢桁架梁段把大桥引向马林县海岸，桁架一节接一节，高度逐渐降低。和全桥一样，这里也是上下两层桥面，各走一个方向。",
       en:"West of the main channel, a chain of steel truss spans steps down toward the Marin shore, one section after another. As on the rest of the bridge, there are two decks here, each carrying one direction of traffic."}},
  rsrbridge3: {k:{zh:"大桥引桥", en:"Bridge approach"}, y:"1956",
    d:{zh:"马林引桥是大桥西端上岸前的一段，在圣昆廷角登陆，580 号州际公路从这里继续通往圣拉斐尔。低矮的桥段贴近水面，回头可以望见对岸的里士满和远处的塔玛尔佩斯山。",
       en:"The Marin approach brings the bridge ashore at Point San Quentin, where Interstate 580 continues toward San Rafael. The low spans run close to the water, with Richmond across the bay behind and Mount Tamalpais in the distance."}},

  ggbridge: {k:{zh:"悬索桥", en:"Suspension bridge"}, y:"1937", a:{zh:"约瑟夫·施特劳斯（总工程师）、欧文·莫罗（建筑师）", en:"Joseph Strauss (chief engineer), Irving Morrow (architect)"}, h:227,
    d:{zh:"金门大桥 1937 年通车，横跨旧金山湾口的金门海峡，主跨约 1280 米，通车时是世界上最长的悬索桥。桥塔高出水面约 227 米；标志性的“国际橙”既与周围的山海相衬，也让大桥在浓雾中更容易被看见。",
       en:"Opened in 1937, the Golden Gate Bridge spans the strait at the mouth of San Francisco Bay. Its main span of about 1,280 m was the longest of any suspension bridge in the world at the time. The towers rise about 227 m above the water, and the International Orange color suits the setting and stands out in fog."},
    x:[{zh:"主跨约 1280 米", en:"Main span: about 1,280 m"}]},
  fortpoint: {k:{zh:"海防要塞", en:"Coastal fort"}, y:"1861",
    d:{zh:"波因特堡是一座三层砖石海防要塞，1861 年完工，用来守卫金门海峡。修建金门大桥时，工程师专门设计了一道钢拱从要塞上方跨过，把它完整保留了下来。如今这里是国家历史遗址，可以在城墙上近距离仰望大桥底部。",
       en:"Fort Point is a three-tier brick fort completed in 1861 to guard the Golden Gate. When the bridge was built, its engineers added a steel arch over the fort so that it could be saved. Now a National Historic Site, it offers a close view of the underside of the bridge."}},

  /* ---------------- East Bay ---------------- */
  tribunetower: {k:{zh:"报社大楼", en:"Newspaper tower"}, y:"1923", a:{zh:"爱德华·T·福克斯", en:"Edward T. Foulkes"},
    d:{zh:"奥克兰论坛报大楼 1923 年为《奥克兰论坛报》建造，是奥克兰市中心天际线上最好认的建筑之一。塔顶装有四面时钟和红色霓虹灯字样 TRIBUNE，夜里格外醒目。报社后来迁出，大楼改作办公使用。",
       en:"Built in 1923 for the Oakland Tribune newspaper, this tower is one of the best-known shapes on the downtown Oakland skyline. Its top carries a four-sided clock and red neon “TRIBUNE” signs that glow at night. The newspaper has since moved out, and the building now holds offices."}},
  oakcityhall: {k:{zh:"市政厅", en:"City hall"}, y:"1914", a:{zh:"帕尔默与霍恩博斯特尔", en:"Palmer & Hornbostel"}, h:98, fl:18,
    d:{zh:"奥克兰市政厅 1914 年落成，是美国最早的高层政府办公楼之一，层层收进的造型配上顶部钟塔，常被比作一座婚礼蛋糕。它在 1989 年地震中受损，后来在地基下加装隔震支座进行加固。",
       en:"Completed in 1914, Oakland City Hall was one of the first high-rise government buildings in the United States. Its stepped Beaux-Arts form, topped by a clock tower, is often compared to a wedding cake. After damage in the 1989 earthquake it was strengthened with base isolators that let the ground move beneath it."}},
  paramount: {k:{zh:"装饰艺术剧院", en:"Art Deco theatre"}, y:"1931", a:{zh:"蒂莫西·弗鲁格", en:"Timothy L. Pflueger"},
    d:{zh:"派拉蒙剧院 1931 年开幕，由旧金山建筑师蒂莫西·弗鲁格设计，是美国保存最完好的装饰艺术风格电影宫之一。正立面高大的马赛克画描绘两个巨人提着木偶。1970 年代初修复后改为演出场所，现为国家历史地标。",
       en:"Opened in 1931 and designed by Timothy Pflueger, the Paramount is one of the finest surviving Art Deco movie palaces in America. Its tall tile mosaic shows two giant figures working puppets. Restored in the early 1970s as a performing arts venue, it is now a National Historic Landmark."}},
  foxoakland: {k:{zh:"剧院", en:"Theatre"}, y:"1928", a:{zh:"威克斯与戴", en:"Weeks and Day"},
    d:{zh:"福克斯剧院 1928 年作为电影宫开幕，外立面混合了摩尔式和印度式装饰，内部金碧辉煌。它 1966 年停业，空置了四十多年，2009 年修复后重新开放，如今是演唱会场地，奥克兰艺术学校也设在楼内。",
       en:"The Fox opened as a movie palace in 1928, its richly decorated front mixing Moorish and Indian motifs. It closed in 1966 and stood empty for over forty years before a restoration reopened it in 2009. Today it hosts concerts and also houses the Oakland School for the Arts."}},
  lakemerritt: {k:{zh:"城市湖泊与公园", en:"City lake and park"},
    d:{zh:"梅里特湖是奥克兰市中心的一片咸水潟湖，经水道与海湾相通。1870 年它被设为美国第一个官方野生动物保护区。湖边有古典式藤架柱廊，环湖的“光之项链”路灯 1925 年首次点亮，至今仍是夜晚的地标。",
       en:"Lake Merritt is a tidal saltwater lagoon in the heart of Oakland, linked to the bay by a channel. In 1870 it became the first official wildlife refuge in the United States. A classical pergola and colonnade stand on its shore, and the “Necklace of Lights” around the lake was first lit in 1925."}},
  lmboathouse: {k:{zh:"船屋", en:"Boathouse"}, y:"1909–1913", a:{zh:"约翰·盖伦·霍华德等", en:"John Galen Howard and others"},
    d:{zh:"梅里特湖船屋最初是 1909 年建成的消防高压泵站，1913 年加建两翼后改作市立船屋。如今这里有湖畔餐厅和划船俱乐部，游客还可以从码头乘坐贡多拉游湖。",
       en:"The boathouse began in 1909 as a high-pressure pumping station for firefighting and became the municipal boathouse when wings were added in 1913. Today it holds a lakeside restaurant and a rowing club, and gondola rides leave from its dock."}},
  oaktemple: {k:{zh:"后期圣徒圣殿", en:"Latter-day Saint temple"}, y:"1964", a:{zh:"哈罗德·W·伯顿", en:"Harold W. Burton"},
    d:{zh:"奥克兰加州圣殿是耶稣基督后期圣徒教会的圣殿，1964 年献堂，建在奥克兰的山坡上。白色建筑上立着五座尖塔，夜里灯光亮起时从海湾对岸也能看到。圣殿本身只对教会成员开放，周围的花园和游客中心则对公众开放。",
       en:"Dedicated in 1964, this temple of The Church of Jesus Christ of Latter-day Saints stands on a hillside above Oakland. Five spires rise from its white walls, and when lit at night they can be seen from across the bay. The temple itself is for church members, but its gardens and visitors' center are open to all."}},
  coliseum: {k:{zh:"体育场", en:"Stadium"}, y:"1966", a:{zh:"SOM 建筑设计事务所", en:"Skidmore, Owings & Merrill"},
    d:{zh:"奥克兰体育场 1966 年启用，是一座下沉式的圆形球场，几十年来同时承办棒球和美式橄榄球比赛。突袭者队 2019 年后迁往拉斯维加斯，运动家队也在 2024 年 9 月打完在这里的最后一场比赛，为奥克兰体育的一段历史画上句号。",
       en:"Opened in 1966, the Coliseum is a sunken bowl that for decades hosted both baseball and American football. The Raiders left for Las Vegas after 2019, and the Athletics played their last game here in September 2024, closing a long chapter of Oakland sports history."}},
  oakarena: {k:{zh:"室内体育馆", en:"Indoor arena"}, y:"1966", a:{zh:"SOM 建筑设计事务所", en:"Skidmore, Owings & Merrill"},
    d:{zh:"奥克兰体育馆与旁边的体育场同年启用，方正的玻璃外墙和外露的结构是 1960 年代现代主义的佳作。金州勇士队 1971 年至 2019 年以这里为主场，期间多次夺得总冠军，之后迁往旧金山的大通中心。",
       en:"The arena opened in 1966 next to the Coliseum; its square glass walls and exposed structure are a fine example of 1960s modernism. The Golden State Warriors played here from 1971 to 2019, winning several championships, before moving to Chase Center in San Francisco."}},
  oakcathedral: {k:{zh:"天主教主教座堂", en:"Catholic cathedral"}, y:"2008", a:{zh:"克雷格·W·哈特曼（SOM）", en:"Craig W. Hartman (SOM)"},
    d:{zh:"基督之光主教座堂位于梅里特湖畔，2008 年落成，取代了在 1989 年地震中受损的旧主教座堂。外层玻璃包裹着一圈木质肋架，室内光线柔和。圣坛后方的巨幅基督像由无数小孔组成，图像取自法国沙特尔主教座堂的一尊雕像。",
       en:"Completed in 2008 on the shore of Lake Merritt, the cathedral replaced one damaged in the 1989 earthquake. A glass skin wraps a frame of wooden ribs, filling the interior with soft light. Behind the altar, an image of Christ formed by thousands of small perforations is based on a sculpture at Chartres Cathedral in France."}},
  oakfederal: {k:{zh:"联邦政府办公楼", en:"Federal office building"}, y:"1993",
    d:{zh:"这座联邦大楼由两座相同的塔楼组成，中间用高大的玻璃圆厅相连，是奥克兰市中心的熟悉景象。它以长期代表东湾的国会议员罗纳德·V·德勒姆斯命名，楼内设有联邦法院和多个联邦机构的办公室。",
       en:"The federal building is made of two matching towers joined by a tall glass rotunda, a familiar sight in downtown Oakland. It is named after Ronald V. Dellums, who represented the East Bay in Congress for many years, and houses federal courts and agency offices."}},
  claremont: {k:{zh:"历史酒店", en:"Historic hotel"}, y:"1915",
    d:{zh:"克莱蒙特酒店 1915 年开业，坐落在伯克利与奥克兰交界的山脚下。白色的大楼和高塔从湾区很多地方都能望见。当地流传着一个故事：这块地当年是在一盘跳棋中赢来的。如今它是一家带俱乐部和水疗中心的酒店。",
       en:"Opened in 1915 at the foot of the Berkeley Hills, where Berkeley meets Oakland, the Claremont is a sprawling white hotel whose tower can be seen from much of the Bay Area. A popular local story says the land was once won in a game of checkers. Today it runs as a hotel, club and spa."}},
  hornet: {k:{zh:"博物馆舰", en:"Museum ship"}, y:"1943",
    d:{zh:"大黄蜂号是埃塞克斯级航空母舰，1943 年服役，二战中在太平洋作战。1969 年，它在太平洋上接回了从月球返回的阿波罗 11 号和 12 号宇航员。如今它停泊在阿拉米达，作为海、空、航天博物馆对外开放。",
       en:"USS Hornet is an Essex-class aircraft carrier commissioned in 1943 that fought in the Pacific in the Second World War. In 1969 it recovered the astronauts of Apollo 11 and Apollo 12 after their return from the Moon. It is now moored at Alameda as a museum of sea, air and space."}},
  tibuilding1: {k:{zh:"历史建筑", en:"Historic building"}, y:"1938", a:{zh:"威廉·佩顿·戴、乔治·W·凯勒姆", en:"William Peyton Day, George W. Kelham"},
    d:{zh:"金银岛是为 1939 年金门国际博览会填海造出的人工岛，一号楼是当年装饰艺术风格的行政大楼。博览会期间，泛美航空的水上飞机以这里为航站楼；原本计划让小岛日后成为旧金山的机场，但二战中海军接管了全岛，计划没有实现。",
       en:"Treasure Island was built on fill for the 1939 Golden Gate International Exposition, and Building One was its Art Deco administration building. During the fair it served as the terminal for Pan Am's flying boats. The island was meant to become San Francisco's airport, but the Navy took it over in the Second World War."}},
  sunoltemple: {k:{zh:"水神庙", en:"Water temple"}, y:"1910", a:{zh:"威利斯·波尔克", en:"Willis Polk"},
    d:{zh:"苏诺尔水神庙 1910 年建成，由建筑师威利斯·波尔克设计，造型仿照意大利蒂沃利的古罗马维斯塔神庙。圆形神庙标出了当年汇集阿拉米达溪和附近井水、再送往旧金山的地点，如今由旧金山公用事业委员会管理。",
       en:"Designed by Willis Polk and finished in 1910, this round temple is modelled on the Roman Temple of Vesta at Tivoli. It marks the place where water from Alameda Creek and nearby wells was gathered and sent toward San Francisco. The site is cared for by the San Francisco Public Utilities Commission."}},
  missionsj: {k:{zh:"西班牙传教站", en:"Spanish mission"}, y:"1797",
    d:{zh:"圣何塞传教站 1797 年建立，是加州 21 座西班牙传教站中的第 14 座。虽然名叫圣何塞，它其实位于今天的弗里蒙特。原来的土坯教堂毁于 1868 年地震，现在看到的教堂是 1980 年代按原貌仔细复建的。",
       en:"Founded in 1797, Mission San José was the fourteenth of California's 21 Spanish missions. Despite its name it stands in today's Fremont, not in the city of San José. The original adobe church fell in the 1868 earthquake; the church seen today is a careful reconstruction finished in the 1980s."}},

  /* ---------------- Silicon Valley campuses ---------------- */
  svmeta: {k:{zh:"企业园区", en:"Corporate campus"}, a:{zh:"弗兰克·盖里（MPK 20–22）", en:"Frank Gehry (MPK 20–22)"},
    d:{zh:"Meta（原 Facebook）总部位于门洛帕克的海湾边。1 Hacker Way 老园区沿用了太阳微系统公司的旧办公楼，围绕一条步行“主街”排布；西侧的 MPK 20、21、22 由弗兰克·盖里设计，是几座长条形办公楼，屋顶覆盖大片花园，其中 MPK 20 于 2015 年启用。",
       en:"Meta, formerly Facebook, is based beside the bay in Menlo Park. The original campus at 1 Hacker Way reuses former Sun Microsystems buildings set around a pedestrian main street. To the west, MPK 20, 21 and 22, designed by Frank Gehry, are long office buildings topped by large rooftop gardens; MPK 20 opened in 2015."}},
  svmeta_b: {p:"svmeta"},
  svmeta_c: {p:"svmeta"},
  svmeta_d: {p:"svmeta"},
  svhp: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"惠普公司总部位于斯坦福研究园区的佩奇米尔路，是几座被草坪和树木环绕的低层现代办公楼。惠普 1939 年由比尔·休利特和戴维·帕卡德创立；2015 年公司一分为二，做个人电脑和打印机的惠普公司（HP Inc.）留在了帕洛阿尔托。",
       en:"HP Inc. has its headquarters on Page Mill Road in Stanford Research Park, in low modern office buildings set among lawns and trees. Hewlett-Packard was founded in 1939 by Bill Hewlett and David Packard; when it split in two in 2015, HP Inc., the maker of PCs and printers, stayed in Palo Alto."}},
  svhpgarage: {k:{zh:"历史遗址", en:"Historic site"},
    d:{zh:"帕洛阿尔托艾迪生大道 367 号后院的这间小木车库，是比尔·休利特和戴维·帕卡德 1939 年创办惠普的地方，他们在这里做出了第一款产品——音频振荡器。1989 年它被列为加州历史地标，称为“硅谷诞生地”；如今由惠普保管，游客可在街边观看。",
       en:"In this small wooden garage behind 367 Addison Avenue, Bill Hewlett and David Packard started HP in 1939 and built their first product, an audio oscillator. In 1989 it became a California Historical Landmark, the “Birthplace of Silicon Valley”. The company still looks after it, and visitors can see it from the street."}},
  svtesla: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"鹿溪路 3500 号位于斯坦福研究园区的山坡上，2010 年代是特斯拉在帕洛阿尔托的总部所在地。2021 年公司总部迁往德克萨斯州奥斯汀；2023 年特斯拉又宣布把全球工程总部设在帕洛阿尔托，车辆、能源和人工智能团队集中在这一带办公。",
       en:"Set on the slopes of Stanford Research Park, 3500 Deer Creek Road was Tesla's Palo Alto headquarters through the 2010s. The company moved its corporate headquarters to Austin, Texas in 2021, and in 2023 made Palo Alto the home of its global engineering headquarters, where vehicle, energy and AI teams work."}},
  svvmware: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"这片园区建在帕洛阿尔托山坡的橡树林间，办公楼顺着地势层层退台，平台和屋顶上种满植物。它曾是虚拟化软件公司 VMware 的总部；2023 年 VMware 被博通公司收购。",
       en:"This campus sits among oak trees on a Palo Alto hillside, its office buildings stepping down the slope in planted terraces. It was the headquarters of VMware, the virtualization software company, which was acquired by Broadcom in 2023."}},
  svvmware_b: {p:"svvmware"},
  svinfiniteloop: {k:{zh:"企业园区", en:"Corporate campus"}, y:"1993",
    d:{zh:"无限循环园区 1993 年启用，六栋办公楼围着一条椭圆形环路和中央草坪排开，地址 Infinite Loop 借用了编程里“无限循环”的说法。这里做了苹果公司二十多年的总部，见证了 iMac、iPod 和 iPhone 的诞生；2017 年总部迁往苹果园区后，这里仍在使用。",
       en:"Opened in 1993, Infinite Loop is a group of six office buildings around an oval road and a central lawn; its address borrows a term from programming. It was Apple's headquarters for over two decades, through the years of the iMac, iPod and iPhone. Apple moved its main base to Apple Park in 2017, but the campus is still in use."}},
  svoracle: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"甲骨文园区坐落在红木海岸的人工湖边，几座圆柱形蓝色玻璃塔楼围着水面排开，常被人比作数据库图标里的“圆柱”。甲骨文 1977 年创立，2020 年把公司总部迁往德克萨斯州，但这里仍是它最重要的园区之一。",
       en:"Oracle's campus stands beside a lagoon in Redwood Shores, where cylindrical blue-glass towers are grouped around the water; people often liken them to the cylinder symbol used for databases. Founded in 1977, Oracle moved its official headquarters to Texas in 2020, but this remains one of its key campuses."}},
  svoracle_b: {p:"svoracle"},
  svoracle_c: {p:"svoracle"},
  svea: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"艺电（Electronic Arts）总部位于红木海岸的海湾边，一组现代办公楼围绕庭院和运动场地布置。艺电 1982 年创立，是全球最大的电子游戏发行商之一，《EA Sports FC》（原 FIFA 系列）、《模拟人生》等游戏都出自这里。",
       en:"Electronic Arts is based by the bay in Redwood Shores, in a group of modern office buildings around courtyards and sports fields. Founded in 1982, EA is one of the world's largest video game publishers, known for series such as EA Sports FC (formerly FIFA) and The Sims."}},
  svea_b: {p:"svea"},
  svgenentech: {k:{zh:"生物科技园区", en:"Biotech campus"},
    d:{zh:"基因泰克 1976 年在南旧金山创立，被视为现代生物技术产业的开端，南旧金山也因此自称“生物科技的诞生地”。园区从山坡上的研究楼一直延伸到海湾边，地址是 DNA 路 1 号；公司 2009 年起成为罗氏集团的全资子公司。",
       en:"Genentech was founded in South San Francisco in 1976 and is widely seen as the start of the modern biotech industry; the city calls itself “the Birthplace of Biotechnology”. The campus runs from research buildings on the hill down to the bayfront at 1 DNA Way. Since 2009 Genentech has been fully owned by Roche."}},
  svgenentech_b: {p:"svgenentech"},
  svgilead: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"吉利德科学总部位于福斯特城的湖边，园区由多栋玻璃办公楼和步行广场组成。公司 1987 年创立，以抗病毒药物著称，研发了多种治疗艾滋病毒和丙型肝炎的药物。",
       en:"Gilead Sciences has its headquarters beside the lagoons of Foster City, in a campus of glass office buildings and walkways. Founded in 1987, the company is known for antiviral medicines, including widely used treatments for HIV and hepatitis C."}},
  svgilead_b: {p:"svgilead"},
  svnvidia: {k:{zh:"企业总部", en:"Corporate headquarters"}, y:"2018–2022", a:{zh:"Gensler", en:"Gensler"},
    d:{zh:"英伟达总部由两座大楼组成：2018 年启用的 Endeavor 和 2022 年启用的 Voyager，都由 Gensler 设计。建筑以三角形为母题，因为三角形是计算机图形的基本单元；巨大的屋顶开满三角形天窗，让阶梯状的室内空间充满自然光。",
       en:"NVIDIA's headquarters consists of two buildings by Gensler: Endeavor, opened in 2018, and Voyager, opened in 2022. Both use the triangle as their theme, since triangles are the basic unit of computer graphics. Huge roofs full of triangular skylights fill the stepped interiors with daylight."}},
  svnvidia_b: {p:"svnvidia"},
  svintel: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"英特尔总部位于圣克拉拉，主楼以联合创始人罗伯特·诺伊斯命名，他也是集成电路的发明人之一。英特尔 1968 年创立，1971 年推出第一款商用微处理器 4004，此后它的芯片成为大多数个人电脑的核心。",
       en:"Intel's headquarters in Santa Clara is named after co-founder Robert Noyce, one of the inventors of the integrated circuit. Founded in 1968, Intel introduced the first commercial microprocessor, the 4004, in 1971, and its chips went on to power most personal computers."}},
  svintel_b: {p:"svintel"},
  svintel_c: {p:"svintel"},
  svamd: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"AMD 总部是圣克拉拉奥古斯丁大道上的一座现代玻璃办公楼。AMD 1969 年创立，为电脑、游戏主机和数据中心设计处理器与图形芯片，2017 年前后把总部从桑尼维尔搬到了这里。",
       en:"AMD's headquarters is a modern glass office building on Augustine Drive in Santa Clara. Founded in 1969, AMD designs processors and graphics chips for computers, game consoles and data centers, and moved its headquarters here from Sunnyvale around 2017."}},
  svamd_b: {p:"svamd"},
  svamat: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"应用材料公司总部位于圣克拉拉鲍尔斯大道，是一片由办公楼和实验楼组成的园区。公司 1967 年创立，生产制造芯片和显示屏所用的设备，是全球最大的半导体设备供应商之一。",
       en:"Applied Materials has its headquarters on Bowers Avenue in Santa Clara, a campus of offices and labs. Founded in 1967, the company makes the machines used to manufacture chips and displays, and is one of the largest suppliers of semiconductor equipment in the world."}},
  svpanw: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"派拓网络总部位于圣克拉拉，由几座弧形玻璃塔楼组成。公司 2005 年创立，名字取自它起步的城市帕洛阿尔托，主营网络安全，最初以新一代防火墙闻名。",
       en:"Palo Alto Networks is based in Santa Clara, in a group of curved glass towers. Founded in 2005 and named after Palo Alto, where it started, the company works in cybersecurity and first became known for its next-generation firewalls."}},
  svservicenow: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"ServiceNow 总部位于圣克拉拉劳森巷，由几座玻璃办公楼组成。公司 2004 年创立，开发企业使用的云端工作流程软件，帮助机构处理 IT、客户服务和人力资源等事务。",
       en:"ServiceNow's headquarters is a group of glass office buildings on Lawson Lane in Santa Clara. Founded in 2004, the company makes cloud software that helps organisations run workflows for IT, customer service and human resources."}},
  svservicenow_b: {p:"svservicenow"},
  svlab126: {k:{zh:"企业研发园区", en:"Corporate R&D campus"},
    d:{zh:"Lab126 是亚马逊的硬件研发部门，位于桑尼维尔莫菲特公园的玻璃办公塔楼里。Kindle 电子阅读器、Echo 智能音箱和 Fire 平板都是在这里开发的；名字里的“126”代表字母表从 A（第 1 个）到 Z（第 26 个）。",
       en:"Lab126 is Amazon's hardware research and development unit, based in glass office towers at Moffett Park in Sunnyvale. Devices such as the Kindle e-reader, Echo smart speakers and Fire tablets were developed here. The “126” in its name stands for the alphabet: 1 for A and 26 for Z."}},
  svlab126_b: {p:"svlab126"},
  svsynopsys: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"新思科技总部位于桑尼维尔，几座玻璃塔楼在 2018 年前后落成。公司 1986 年创立，主营电子设计自动化（EDA）软件，芯片工程师用它来设计和验证复杂的集成电路。",
       en:"Synopsys has its headquarters in Sunnyvale, in glass towers completed around 2018. Founded in 1986, the company makes electronic design automation (EDA) software, which chip engineers use to design and check complex integrated circuits."}},
  svsynopsys_b: {p:"svsynopsys"},
  svadobe: {k:{zh:"企业总部", en:"Corporate headquarters"}, y:"1996–2023",
    d:{zh:"Adobe 总部位于圣何塞市中心，由 1996 年的西塔、1998 年的东塔、2003 年的阿尔马登塔和 2023 年的创始人大楼组成。Adobe 1982 年由约翰·沃诺克和查尔斯·格什克创立，Photoshop 和 PDF 格式都出自这家公司。",
       en:"Adobe's headquarters in downtown San Jose is made up of the West Tower (1996), East Tower (1998), Almaden Tower (2003) and Founders Tower (2023). Adobe was founded in 1982 by John Warnock and Charles Geschke, and created widely used tools such as Photoshop and the PDF format."}},
  svadobe_b: {p:"svadobe"},
  svpaypal: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"PayPal 总部位于圣何塞北第一街，是一组围绕庭院布置的办公楼。PayPal 成立于 1998 年，提供网上支付服务，2002 年被 eBay 收购，2015 年又分拆独立。",
       en:"PayPal's headquarters is a group of office buildings around landscaped courtyards on North First Street in San Jose. Founded in 1998, the online payments company was bought by eBay in 2002 and became independent again in 2015."}},
  svcisco: {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"思科总部园区沿圣何塞北部的塔斯曼大道铺开，由二十多栋按编号排列的四到六层办公楼组成。思科 1984 年创立，生产路由器、交换机等网络设备，世界上大量的互联网流量都经过它的产品。",
       en:"Cisco's headquarters campus spreads along Tasman Drive in north San Jose, with more than twenty numbered office buildings of four to six storeys. Founded in 1984, Cisco makes routers, switches and other networking equipment that carry a large share of the world's internet traffic."}},
  svcisco_b: {p:"svcisco"},
  svcisco_c: {p:"svcisco"},
  svcisco_d: {p:"svcisco"},
  svcisco_e: {p:"svcisco"},
  svcisco_f: {p:"svcisco"},
  svcisco_g: {p:"svcisco"},
  svcisco_h: {p:"svcisco"},
  svsamsung: {k:{zh:"企业总部", en:"Corporate headquarters"}, y:"2015", a:{zh:"NBBJ", en:"NBBJ"},
    d:{zh:"三星半导体美国总部 2015 年落成，由 NBBJ 设计。大楼把办公楼层分组叠放，组与组之间留出开放的花园露台，让员工每隔几层就能到户外交流；从街上看，像一摞彼此错开的盒子。",
       en:"Completed in 2015 and designed by NBBJ, Samsung's semiconductor headquarters stacks groups of office floors with open garden terraces between them, so staff can meet outdoors every few levels. From the street it looks like a pile of offset boxes."}},
  svlinkedin: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"领英总部位于桑尼维尔西莫德大道，是一组现代玻璃办公楼和庭院。领英 2002 年创立，是面向职场的社交网络，2016 年被微软收购。",
       en:"LinkedIn's headquarters is a group of modern glass office buildings and courtyards on West Maude Avenue in Sunnyvale. Founded in 2002, the professional networking service, where people share their work history and look for jobs, was acquired by Microsoft in 2016."}},
  svlinkedin_b: {p:"svlinkedin"},
  svintuit: {k:{zh:"企业总部", en:"Corporate headquarters"},
    d:{zh:"财捷（Intuit）总部位于山景城靠近海湾的马林路一带，园区 2017 年前后落成，楼与楼之间有露台和公共绿地。公司 1983 年创立，开发 TurboTax、QuickBooks 等面向个人和小企业的财务与报税软件。",
       en:"Intuit is based near the bay in Mountain View, where its Marine Way campus opened around 2017 with terraces and shared green spaces between buildings. Founded in 1983, the company makes finance and tax software such as TurboTax and QuickBooks for people and small businesses."}},
  svintuit_b: {p:"svintuit"},
  svintuit_c: {p:"svintuit"},
  svmsft: {k:{zh:"企业园区", en:"Corporate campus"}, a:{zh:"WRNS Studio", en:"WRNS Studio"},
    d:{zh:"微软硅谷园区位于山景城，大量使用木结构和玻璃，几栋楼围绕绿色庭院布置，屋顶也覆盖着植被。园区由 WRNS Studio 设计，按照很高的节能和节水标准建造。",
       en:"Microsoft's Silicon Valley campus in Mountain View is built largely of mass timber and glass, arranged around green courtyards under planted roofs. Designed by WRNS Studio, it was built to very high standards for saving energy and water."}},
  svhangarone: {k:{zh:"飞艇机库", en:"Airship hangar"}, y:"1933",
    d:{zh:"一号机库 1933 年为美国海军的“梅肯号”硬式飞艇而建，长约 345 米，是世界上最大的独立式建筑之一。外墙材料因含有害物质在 2010 年代初被拆除，只剩下钢骨架；2014 年起由谷歌旗下的公司租用并负责修复。旁边的二号、三号机库是二战时期为海军飞艇建造的木结构机库。",
       en:"Hangar One was built in 1933 for the Navy airship USS Macon. About 345 m long, it is one of the largest freestanding structures in the world. Its contaminated outer skin was removed in the early 2010s, leaving the steel frame; since 2014 a Google-owned company has leased it and is responsible for restoring it. Hangars 2 and 3 nearby are wooden blimp hangars from the Second World War."}},
  svhangartwo: {p:"svhangarone"},
  svdish: {k:{zh:"射电望远镜", en:"Radio telescope"}, y:"1961",
    d:{zh:"斯坦福“大碟”是一架直径约 46 米的射电望远镜，1961 年建成，立在斯坦福校园后方的山丘上。它曾用于高层大气研究和与航天器通信；周围的环形步道是附近居民最爱的散步路线之一。",
       en:"The Stanford Dish is a radio telescope about 46 m across, built in 1961 on the foothills behind the Stanford campus. It has been used to study the upper atmosphere and to communicate with spacecraft. The loop trail around it is one of the most popular walks in the area."}},
  svstadium: {k:{zh:"体育场", en:"Stadium"}, y:"2014", a:{zh:"HNTB", en:"HNTB"},
    d:{zh:"李维斯体育场 2014 年在圣克拉拉启用，是旧金山 49 人队的主场，约有 6.8 万个座位。西侧高耸的包厢塔楼是它的标志，屋顶花园和太阳能板让它成为较早注重环保的体育场之一。2016 年第 50 届超级碗在这里举行。",
       en:"Opened in 2014 in Santa Clara, Levi's Stadium is the home of the San Francisco 49ers and holds about 68,000 people. A tall suite tower on the west side is its main feature, and a green roof and solar panels made it an early example of a greener stadium. It hosted Super Bowl 50 in 2016."}},
  svchm: {k:{zh:"博物馆", en:"Museum"},
    d:{zh:"计算机历史博物馆位于山景城，收藏着世界上规模最大的计算机文物之一，从早期计算器、大型机到个人电脑和互联网时代的设备。常设展“革命”讲述了约两千年的计算发展史，馆内还有几台仍能运转的历史计算机。",
       en:"The Computer History Museum in Mountain View holds one of the largest collections of computing artifacts in the world, from early calculators and mainframes to personal computers and internet-era devices. Its main exhibition, Revolution, traces some two thousand years of computing, and several historic machines are kept in working order."}},

  /* ---------------- San José ---------------- */
  sjcityhall: {k:{zh:"市政厅", en:"City hall"}, y:"2005", a:{zh:"理查德·迈耶", en:"Richard Meier"}, fl:18,
    d:{zh:"圣何塞市政厅 2005 年落成，由理查德·迈耶设计，由一座 18 层的白色办公塔楼和一个玻璃圆厅组成。圆厅是市民聚会和举办活动的公共空间，面向开阔的市政广场。",
       en:"San José City Hall, completed in 2005, was designed by Richard Meier. It pairs an 18-storey white office tower with a glass rotunda, a public space for gatherings and events that opens onto a wide civic plaza."}},
  sjcathedral: {k:{zh:"天主教主教座堂", en:"Catholic cathedral"}, y:"1877",
    d:{zh:"圣约瑟夫主教座堂位于圣何塞市中心，现存教堂 1877 年落成，有一座大穹顶和两座钟楼。它所在的堂区是加州最古老的堂区之一；1981 年成为圣何塞教区的主教座堂，1997 年获封为宗座圣殿。",
       en:"Completed in 1877, the Cathedral Basilica of St. Joseph in downtown San Jose has a large dome and two bell towers. Its parish is one of the oldest in California. It became the cathedral of the Diocese of San Jose in 1981 and was named a minor basilica in 1997."}},
  sjwinchester: {k:{zh:"历史宅邸", en:"Historic mansion"}, y:"1886–1922",
    d:{zh:"温彻斯特神秘屋是莎拉·温彻斯特的宅邸，她的丈夫出自制造温彻斯特步枪的家族。从 1886 年起，宅子几乎不停地扩建，直到她 1922 年去世。屋里约有 160 个房间，还有通向天花板的楼梯和开向墙壁的门，如今作为博物馆对外开放。",
       en:"The Winchester Mystery House was the home of Sarah Winchester, whose husband's family made the famous rifle. Building went on almost without pause from 1886 until her death in 1922. The house has about 160 rooms, with stairs that end at the ceiling and doors that open onto walls, and is now open to visitors."}},
  sjrosicrucian: {k:{zh:"博物馆", en:"Museum"},
    d:{zh:"玫瑰十字埃及博物馆位于圣何塞的玫瑰十字公园内，建筑仿照古埃及神庙的样式。馆内陈列木乃伊、雕像和日常器物，是美国西部展出古埃及文物最多的博物馆之一，游客还可以走进一座复制的岩墓。",
       en:"The Rosicrucian Egyptian Museum in San Jose's Rosicrucian Park is built in the style of an ancient Egyptian temple. It displays mummies, statues and everyday objects, one of the largest collections of Egyptian artifacts on show in the western United States, and visitors can walk through a replica rock tomb."}},

  /* ---------------- San Francisco: Civic Center and around ---------------- */
  sfcityhall: {k:{zh:"市政厅", en:"City hall"}, y:"1915", a:{zh:"小阿瑟·布朗", en:"Arthur Brown Jr."}, h:94,
    d:{zh:"旧金山市政厅 1915 年落成，取代在 1906 年大地震中毁坏的旧市政厅，由小阿瑟·布朗设计。镶金装饰的穹顶高约 94 米，比华盛顿美国国会大厦的穹顶还高。1954 年，乔·迪马乔和玛丽莲·梦露在这里结婚。",
       en:"Completed in 1915 to replace a city hall ruined in the 1906 earthquake, San Francisco City Hall was designed by Arthur Brown Jr. Its gilded dome rises about 94 m, higher than the dome of the US Capitol. Joe DiMaggio and Marilyn Monroe were married here in 1954."}},
  sfopera: {k:{zh:"歌剧院", en:"Opera house"}, y:"1932", a:{zh:"小阿瑟·布朗", en:"Arthur Brown Jr."},
    d:{zh:"战争纪念歌剧院 1932 年开幕，由小阿瑟·布朗设计，是旧金山歌剧院和旧金山芭蕾舞团的主场。1945 年创立联合国的会议在这里召开，1951 年对日和约也在这里签署。",
       en:"Opened in 1932 and designed by Arthur Brown Jr., the War Memorial Opera House is home to San Francisco Opera and San Francisco Ballet. The 1945 conference that created the United Nations met here, and the 1951 peace treaty with Japan was signed on its stage."}},
  sfveterans: {k:{zh:"纪念建筑", en:"Memorial building"}, y:"1932", a:{zh:"小阿瑟·布朗", en:"Arthur Brown Jr."},
    d:{zh:"退伍军人纪念大楼与歌剧院隔着纪念庭院相对，两座楼几乎一模一样，1932 年同时落成。楼内的赫布斯特剧院是 1945 年《联合国宪章》签署的地方；如今这里设有退伍军人组织的办公室和演出空间。",
       en:"The Veterans Building faces its near-twin, the Opera House, across the memorial court; both opened in 1932. The United Nations Charter was signed in its Herbst Theatre in 1945. Today it houses veterans' organizations and performance spaces."}},
  sfasianart: {k:{zh:"博物馆", en:"Museum"}, y:"1917", a:{zh:"乔治·W·凯勒姆（原图书馆）、盖·奥伦蒂（2003 改建）", en:"George W. Kelham (library); Gae Aulenti (2003 conversion)"},
    d:{zh:"亚洲艺术博物馆所在的大楼原是 1917 年落成的旧金山主图书馆，2003 年由意大利建筑师盖·奥伦蒂改建为博物馆，2023 年又在侧面加建了一座新展馆。馆藏涵盖亚洲各地几千年的艺术品，是美国同类博物馆中规模最大的之一。",
       en:"The Asian Art Museum occupies San Francisco's former Main Library, completed in 1917. Italian architect Gae Aulenti converted it into a museum in 2003, and a new pavilion was added in 2023. Its collection spans thousands of years of art from across Asia, one of the largest of its kind in the United States."}},
  sfdavies: {k:{zh:"音乐厅", en:"Concert hall"}, y:"1980", a:{zh:"SOM 建筑设计事务所", en:"Skidmore, Owings & Merrill"},
    d:{zh:"戴维斯交响音乐厅 1980 年启用，由 SOM 设计，弧形的玻璃立面朝向范内斯大道。这里是旧金山交响乐团的主场，名字来自主要捐赠人路易丝·M·戴维斯。",
       en:"Davies Symphony Hall opened in 1980, designed by Skidmore, Owings & Merrill, with a curved glass front facing Van Ness Avenue. It is the home of the San Francisco Symphony and is named after its leading donor, Louise M. Davies."}},
  sfstmarys: {k:{zh:"天主教主教座堂", en:"Catholic cathedral"}, y:"1971", a:{zh:"彼得罗·贝鲁斯基、皮埃尔·路易吉·奈尔维", en:"Pietro Belluschi, Pier Luigi Nervi"},
    d:{zh:"圣母升天主教座堂 1971 年落成，是旧金山天主教总教区的主教座堂，取代了毁于火灾的旧座堂。四片双曲抛物面混凝土薄壳从方形基座升起，在顶上交汇成十字形的彩色玻璃天窗，穹顶高约 58 米。",
       en:"Completed in 1971, St. Mary's is the cathedral of the Catholic Archdiocese of San Francisco, replacing an earlier church lost to fire. Four curved concrete shells, each a hyperbolic paraboloid, rise from a square base and meet at the top in a cross of stained glass about 58 m above the floor."}},
  sfpagoda: {k:{zh:"宝塔", en:"Pagoda"}, y:"1968", a:{zh:"谷口吉郎", en:"Yoshirō Taniguchi"},
    d:{zh:"和平塔位于日本城的和平广场，1968 年落成，是旧金山的姊妹城市大阪赠送的礼物。这座五层混凝土塔由日本建筑师谷口吉郎设计，象征日美两国人民之间的友谊与和平。",
       en:"The Peace Pagoda in Japantown's Peace Plaza was completed in 1968 as a gift from Osaka, San Francisco's sister city. Designed by Japanese architect Yoshirō Taniguchi, the five-tier concrete pagoda stands for friendship and peace between the peoples of Japan and the United States."}},
  sfmission: {k:{zh:"传教站与教堂", en:"Mission and basilica"}, y:"1791",
    d:{zh:"多洛雷斯传教站正式名称为亚西西的圣方济各传教站，1776 年建立。现存的土坯小教堂 1791 年完工，是旧金山最古老的完整建筑，经历了 1906 年大地震依然屹立。旁边装饰华丽的大教堂建于 20 世纪初，后被定为宗座圣殿。",
       en:"Mission Dolores, formally Mission San Francisco de Asís, was founded in 1776. Its small adobe chapel, finished in 1791, is the oldest intact building in San Francisco and survived the 1906 earthquake. Beside it stands the more ornate basilica, built in the early twentieth century."}},
  paintedladies: {k:{zh:"维多利亚式住宅", en:"Victorian houses"}, y:"1892–1896",
    d:{zh:"“彩绘女士”是阿拉莫广场东侧斯坦纳街上的一排维多利亚式木屋，19 世纪 90 年代由开发商马修·卡瓦诺建造。房子漆成几种柔和的颜色，背后衬着市中心的天际线，是旧金山最常出现在明信片和影视剧里的画面之一。",
       en:"The Painted Ladies are a row of Victorian wooden houses on Steiner Street facing Alamo Square, built in the 1890s by developer Matthew Kavanaugh. Painted in soft colors and set against the downtown skyline, they are among the most photographed scenes in San Francisco and appear in many films and TV shows."}},
  sutrotower: {k:{zh:"电视广播塔", en:"TV and radio tower"}, y:"1973", h:298,
    d:{zh:"苏特罗塔 1973 年建成，高约 298 米，立在城市中部的山顶上，红白相间的三脚钢架常常从雾里探出头来。它向整个湾区发射电视和广播信号，名字来自曾拥有这片山地的前市长阿道夫·苏特罗。",
       en:"Completed in 1973, Sutro Tower stands about 298 m tall on a hill in the middle of the city, its red-and-white three-legged frame often rising out of the fog. It broadcasts television and radio across the Bay Area and is named after Adolph Sutro, the former mayor who once owned the land."}},
  sfdavidson: {k:{zh:"纪念十字架", en:"Memorial cross"}, y:"1934", h:31,
    d:{zh:"戴维森山是旧金山最高的山，海拔约 282 米。山顶的混凝土十字架高约 31 米，1934 年落成，多年来每逢复活节都在这里举行日出礼拜。1997 年起，十字架归一个美国亚美尼亚裔社团所有，用来纪念亚美尼亚大屠杀的遇难者。",
       en:"Mount Davidson is the highest hill in San Francisco, about 282 m above sea level. The concrete cross on its top, about 31 m tall, was completed in 1934, and Easter sunrise services have been held here for decades. Since 1997 it has been owned by an Armenian American group as a memorial to the victims of the Armenian Genocide."}},
  legionofhonor: {k:{zh:"美术馆", en:"Art museum"}, y:"1924", a:{zh:"乔治·阿普尔加思", en:"George Applegarth"},
    d:{zh:"荣勋宫美术馆 1924 年开馆，按约四分之三的比例仿建巴黎的荣誉军团宫，用来纪念一战中阵亡的加州士兵。它坐落在林肯公园的高地上，可以眺望金门海峡；庭院里有一尊罗丹《思想者》的铸像。",
       en:"Opened in 1924, the Legion of Honor is a three-quarter-scale version of the Palais de la Légion d'Honneur in Paris, built to honor Californian soldiers who died in the First World War. It stands on high ground in Lincoln Park overlooking the Golden Gate, and a cast of Rodin's The Thinker sits in its courtyard."}},

  /* ---------------- San Francisco: downtown ---------------- */
  transamerica: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1972", a:{zh:"威廉·佩雷拉", en:"William Pereira"}, h:260, fl:48,
    d:{zh:"泛美金字塔 1972 年落成，由威廉·佩雷拉设计，高约 260 米，尖锐的四棱锥造型是旧金山天际线的象征。它做了四十多年的全市最高建筑；两侧伸出的“翅膀”里分别是电梯井和楼梯间。",
       en:"Completed in 1972 and designed by William Pereira, the Transamerica Pyramid rises about 260 m to a sharp point, an icon of the San Francisco skyline. It was the city's tallest building for over forty years. The two “wings” on its sides hold the elevators and a stairway."}},
  salesforcetower: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2018", a:{zh:"佩里·克拉克·佩里建筑事务所", en:"Pelli Clarke Pelli"}, h:326, fl:61,
    d:{zh:"赛富时大厦 2018 年落成，高约 326 米，是旧金山最高的建筑。它由佩里·克拉克·佩里事务所设计，圆角方柱的塔身越往上越收窄。塔顶装有艺术家吉姆·坎贝尔创作的大型 LED 灯光作品，夜里播放流动的影像。",
       en:"Completed in 2018, Salesforce Tower is about 326 m tall, the tallest building in San Francisco. Designed by Pelli Clarke Pelli, it is a rounded square shaft that tapers toward the top. Its crown holds a large LED artwork by Jim Campbell that shows moving images at night."}},
  transitcenter: {k:{zh:"交通枢纽与屋顶公园", en:"Transit hub and rooftop park"}, y:"2018", a:{zh:"佩里·克拉克·佩里建筑事务所", en:"Pelli Clarke Pelli"},
    d:{zh:"赛富时交通中心 2018 年启用，取代了旧的跨湾巴士总站，波浪形的白色穿孔金属外墙绵延四个街区。屋顶是一座约 2 公顷的城市公园，有步道、花园和露天剧场，还能从街面乘小型缆车直上屋顶。",
       en:"Opened in 2018 to replace the old Transbay Terminal, the Salesforce Transit Center stretches four blocks behind a wavy white skin of perforated metal. On its roof is a park of about 2 ha with paths, gardens and an amphitheater, reached by a small gondola from the street."}},
  fremont181: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"2018", a:{zh:"Heller Manus 建筑事务所", en:"Heller Manus Architects"}, h:244,
    d:{zh:"弗里蒙特街 181 号 2018 年落成，高约 244 米，下部是办公楼层，上部是住宅。外立面上醒目的斜向钢支撑既是造型特色，也是抗震结构的一部分，这座塔楼按很高的抗震标准设计。",
       en:"Completed in 2018, 181 Fremont is about 244 m tall, with offices on the lower floors and homes above. The diagonal steel braces on its facade are both its signature look and part of a structure designed to a very high earthquake standard."}},
  millennium: {k:{zh:"住宅塔楼", en:"Residential tower"}, y:"2009", a:{zh:"Handel 建筑事务所", en:"Handel Architects"}, h:197, fl:58,
    d:{zh:"千禧塔 2009 年落成，高约 197 米，是旧金山最高的住宅楼之一。建成后不久，人们发现大楼在下沉并向西北倾斜，引起广泛关注；后来工程师沿一侧加打深桩进行加固。",
       en:"Completed in 2009, Millennium Tower is a 197 m residential tower. Soon after it opened, it was found to be sinking and leaning to the northwest, which drew wide attention; engineers later added deep piles along one side to stabilize it."}},
  bofa555: {k:{zh:"摩天大楼", en:"Skyscraper"}, y:"1969", a:{zh:"Wurster, Bernardi & Emmons 与 SOM", en:"Wurster, Bernardi & Emmons with SOM"}, fl:52,
    d:{zh:"加利福尼亚街 555 号 1969 年落成，原为美国银行总部。深红色花岗岩外墙配上锯齿状的凸窗，随着光线变化呈现不同深浅。它曾是旧金山最高的建筑；广场上一座黑色花岗岩雕塑被人们戏称为“银行家之心”。",
       en:"Completed in 1969 as the headquarters of Bank of America, 555 California Street is clad in dark red granite, with saw-tooth bay windows that catch the changing light. It was once the city's tallest building. A black granite sculpture on its plaza is nicknamed the “Banker's Heart”."}},
  embarcadero: {k:{zh:"建筑群", en:"Building complex"}, y:"1971–1982", a:{zh:"约翰·波特曼", en:"John Portman"},
    d:{zh:"内河码头中心位于金融区东端，由四座办公塔楼和一家凯悦酒店组成，1971 至 1982 年间按约翰·波特曼的设计陆续建成。各楼之间以空中步道和商店相连；节日期间，塔楼的轮廓会用一串串灯光勾勒出来。",
       en:"Embarcadero Center is a complex of four office towers and a Hyatt hotel at the east end of the Financial District, designed by John Portman and built between 1971 and 1982. Raised walkways and shops link the buildings, and in the holiday season their outlines are traced with lights."}},
  ferrybuilding: {k:{zh:"渡轮码头与市场", en:"Ferry terminal and market"}, y:"1898", a:{zh:"A·佩奇·布朗", en:"A. Page Brown"}, h:75,
    d:{zh:"渡轮大厦 1898 年启用，钟楼高约 75 米，仿照西班牙塞维利亚大教堂的吉拉尔达塔。海湾上的大桥建成之前，它是全美最繁忙的交通枢纽之一。2003 年修复后，长廊变成了美食市场，渡轮仍从大楼后面的码头出发。",
       en:"Opened in 1898, the Ferry Building has a clock tower about 75 m high modelled on the Giralda tower of Seville Cathedral. Before the bay bridges were built, it was one of the busiest transit hubs in the country. Since a 2003 restoration its long hall has been a food market, and ferries still leave from behind it."}},
  rincon: {k:{zh:"住宅塔楼", en:"Residential tower"}, y:"2008",
    d:{zh:"林康山一号是林康山上的一座住宅塔楼，2008 年落成，紧挨着海湾大桥的引桥。塔顶装有一个大水箱，作为调谐阻尼器在强风或地震时减小楼体晃动。",
       en:"One Rincon Hill is a residential tower on Rincon Hill, completed in 2008 right beside the Bay Bridge approach. A large water tank at the top acts as a tuned damper, reducing sway in strong winds or earthquakes."}},
  sfcolumbus: {k:{zh:"历史建筑", en:"Historic building"}, y:"1907", a:{zh:"Salfield & Kohlberg", en:"Salfield & Kohlberg"},
    d:{zh:"哥伦布大厦是一座外覆绿色铜皮的熨斗形大楼，位于北滩、唐人街和金融区交汇处的三角地块上，1907 年落成。它常与背后的泛美金字塔一起入镜；导演弗朗西斯·福特·科波拉的电影公司从 1970 年代起就在这里办公。",
       en:"Columbus Tower is a green, copper-clad flatiron building on a triangular lot where North Beach, Chinatown and the Financial District meet. Completed in 1907, it is often photographed with the Transamerica Pyramid behind it. Since the 1970s it has been home to Francis Ford Coppola's film company."}},
  sfoldmint: {k:{zh:"历史建筑", en:"Historic building"}, y:"1874", a:{zh:"艾尔弗雷德·B·马利特", en:"Alfred B. Mullett"},
    d:{zh:"旧金山旧铸币厂 1874 年落成，是一座希腊复兴风格的石造建筑，人称“花岗岩女士”。1906 年地震和大火中，员工奋力守住了大楼，它成为附近少数幸存的建筑之一，金库里的黄金也得以保全，支持了城市灾后重建。",
       en:"Finished in 1874, the Old Mint is a Greek Revival stone building nicknamed “The Granite Lady”. During the 1906 earthquake and fire its workers fought to save it, and it was one of the few buildings nearby to survive, keeping the gold in its vaults safe for the city's rebuilding."}},
  sfsspp: {k:{zh:"天主教堂", en:"Catholic church"}, y:"1924", a:{zh:"查尔斯·范托尼", en:"Charles Fantoni"},
    d:{zh:"圣彼得与圣保罗教堂面向北滩的华盛顿广场，1924 年落成，两座白色尖塔是这一带最醒目的地标。这座天主教堂长期服务意大利裔社区，弥撒使用英语、意大利语和粤语。",
       en:"Facing Washington Square in North Beach, Saints Peter and Paul Church was completed in 1924, and its twin white spires are the neighborhood's best-known landmark. The Catholic church has long served the Italian community, with Masses in English, Italian and Cantonese."}},
  sfmoma: {k:{zh:"现代艺术博物馆", en:"Modern art museum"}, y:"1995 / 2016", a:{zh:"马里奥·博塔；斯诺赫塔（2016 扩建）", en:"Mario Botta; Snøhetta (2016 expansion)"},
    d:{zh:"旧金山现代艺术博物馆创立于 1935 年，是美国西海岸第一座专门展示现当代艺术的博物馆。1995 年它迁入马里奥·博塔设计的红砖建筑，中央黑白条纹的斜切圆形天窗十分醒目；2016 年斯诺赫塔设计的白色波纹扩建部分落成，展厅面积大大增加。",
       en:"Founded in 1935, SFMOMA was the first museum on the West Coast devoted to modern and contemporary art. In 1995 it moved into Mario Botta's brick building with its striped, slanted round skylight. Snøhetta's rippled white extension, opened in 2016, greatly enlarged the galleries."}},
  sfdewey: {k:{zh:"纪念碑与广场", en:"Monument and square"}, y:"1903", a:{zh:"罗伯特·艾特肯（雕塑）、牛顿·撒普（建筑）", en:"Robert Aitken (sculptor), Newton J. Tharp (architect)"},
    d:{zh:"联合广场中央的杜威纪念碑 1903 年由西奥多·罗斯福总统主持揭幕，纪念 1898 年杜威海军上将在马尼拉湾的胜利。约 29 米高的科林斯柱顶上立着胜利女神像。广场四周是旧金山主要的购物和酒店区。",
       en:"The Dewey Monument at the center of Union Square was dedicated in 1903 by President Theodore Roosevelt. It honors Admiral Dewey's victory at Manila Bay in 1898, with a figure of Victory on top of a Corinthian column about 29 m tall. Around the square lies the city's main shopping and hotel district."}},
  sflefty: {k:{zh:"开合桥", en:"Bascule bridge"}, y:"1933",
    d:{zh:"莱夫蒂·欧杜尔桥是第三街跨越米申溪的开合桥，1933 年启用，桥头悬着巨大的混凝土配重，整段桥面可以抬起让船只通过。它以出生在旧金山的棒球名将莱夫蒂·欧杜尔命名，就在甲骨文球场旁边。",
       en:"The Lefty O'Doul Bridge carries Third Street over Mission Creek. Opened in 1933, it is a bascule bridge: a huge concrete counterweight lets the whole deck tilt up for boats. It is named after Lefty O'Doul, a San Francisco-born baseball star, and stands right next to Oracle Park."}},
  oraclepark: {k:{zh:"棒球场", en:"Ballpark"}, y:"2000", a:{zh:"HOK Sport（现 Populous）", en:"HOK Sport (now Populous)"},
    d:{zh:"甲骨文球场 2000 年启用，是旧金山巨人队的主场，红砖立面紧邻海湾。右外野墙外就是麦科维湾，飞出场外的全垒打会直接落进水里，常有球迷划着皮划艇在湾里等球。左外野后方立着巨型饮料瓶和棒球手套雕塑。",
       en:"Opened in 2000, Oracle Park is the home of the San Francisco Giants, a brick ballpark right on the bay. Beyond the right-field wall lies McCovey Cove, where home runs can land in the water and fans wait in kayaks to catch them. A giant soda bottle and baseball glove stand beyond left field."}},
  chasecenter: {k:{zh:"室内体育馆", en:"Indoor arena"}, y:"2019", a:{zh:"Manica 建筑事务所", en:"Manica Architecture"},
    d:{zh:"大通中心 2019 年在米申湾启用，是金州勇士队的主场，可容纳约 1.8 万名观众。圆润的白色建筑周围是公共广场和办公楼，平时也举办演唱会和其他活动。",
       en:"Opened in 2019 in Mission Bay, Chase Center is home to the Golden State Warriors and seats about 18,000 people. Its rounded white form sits among a public plaza and office buildings, and it also hosts concerts and other events."}},

  /* ---------------- San Francisco: hills, north shore, waterfront ---------------- */
  coittower: {k:{zh:"纪念塔", en:"Memorial tower"}, y:"1933", a:{zh:"小阿瑟·布朗、亨利·霍华德", en:"Arthur Brown Jr., Henry Howard"}, h:64,
    d:{zh:"科伊特塔 1933 年建在电报山顶，高约 64 米，用莉莉·希区柯克·科伊特留给城市、用于美化旧金山的遗赠修建。塔底大厅的壁画 1934 年由二十多位艺术家共同完成，描绘了大萧条时期加州人的劳动与生活。",
       en:"Built in 1933 on top of Telegraph Hill, Coit Tower is about 64 m tall and was paid for with a gift that Lillie Hitchcock Coit left to beautify the city. The murals in its base, painted in 1934 by more than twenty artists, show working life in Depression-era California."}},
  gracecathedral: {k:{zh:"圣公会主教座堂", en:"Episcopal cathedral"}, y:"1964", a:{zh:"刘易斯·P·霍巴特", en:"Lewis P. Hobart"},
    d:{zh:"恩典座堂位于诺布山顶，是圣公会加州教区的主教座堂，1928 年动工、1964 年完工。它采用法国哥特式样，却以钢筋混凝土建造。正门是佛罗伦萨洗礼堂“天堂之门”的复制品，室内外各有一座迷宫图案，供人安静地行走默想。",
       en:"Grace Cathedral, the Episcopal cathedral on top of Nob Hill, was begun in 1928 and finished in 1964. It follows French Gothic forms but is built of reinforced concrete. Its main doors are casts of Ghiberti's Gates of Paradise in Florence, and two labyrinths, inside and out, invite quiet walking."}},
  palacefa: {k:{zh:"博览会建筑", en:"Exposition building"}, y:"1915", a:{zh:"伯纳德·梅贝克", en:"Bernard Maybeck"},
    d:{zh:"艺术宫是 1915 年巴拿马-太平洋国际博览会留下、至今仍在原址的唯一建筑，由伯纳德·梅贝克设计，高大的圆顶和柱廊倒映在潟湖里。它原本用临时材料搭建，1960 年代按原样用混凝土重建，如今是散步和拍照的热门地点。",
       en:"The Palace of Fine Arts is the only building of the 1915 Panama-Pacific International Exposition still standing on its original site. Designed by Bernard Maybeck, its rotunda and colonnades are reflected in a lagoon. First built of temporary materials, it was rebuilt in concrete in the 1960s and is a favorite place to walk and take photos."}},
  alcatraz: {k:{zh:"岛屿与历史遗址", en:"Island and historic site"},
    d:{zh:"恶魔岛位于海湾中央。1854 年，美国西海岸第一座灯塔在这里点亮，此后小岛成为军事要塞和军事监狱；1934 至 1963 年间是联邦监狱，关押过阿尔·卡彭等重犯。1969 至 1971 年美洲原住民曾占领该岛，如今它是国家公园的一部分。",
       en:"Alcatraz sits in the middle of the bay. The first lighthouse on the US West Coast was lit here in 1854, and the island later became a fort and military prison. From 1934 to 1963 it was a federal penitentiary that held prisoners such as Al Capone. Native American activists occupied it from 1969 to 1971; today it is part of a national park."}},
  pier39: {k:{zh:"码头商业区", en:"Waterfront pier"}, y:"1978",
    d:{zh:"39 号码头 1978 年开放，是渔人码头一带最热闹的地方，两层木栈道两旁排满商店和餐厅。从码头尽头可以望见恶魔岛、金门大桥和海湾大桥。",
       en:"Pier 39 opened in 1978 and is the busiest part of the Fisherman's Wharf area, with two levels of wooden walkways lined with shops and restaurants. From its far end visitors can see Alcatraz, the Golden Gate Bridge and the Bay Bridge."}},
  pier39b: {k:{zh:"商店街", en:"Shopping street"}, y:"1978",
    d:{zh:"码头上的商店街用旧木料和木栈道营造出老港口的气氛，商店、小吃摊和街头艺人沿着两层步道排开。这里一年四季游客不断，附近也有海湾游船的出发码头。",
       en:"The shopping street on the pier uses weathered wood and boardwalks to recall an old waterfront. Shops, snack stands and street performers line its two levels; it is busy with visitors all year, and bay cruise boats leave nearby."}},
  pier39c: {k:{zh:"旋转木马与海狮观赏区", en:"Carousel and sea lion docks"},
    d:{zh:"码头上有一座双层的威尼斯式旋转木马，是拍照的热门地点。码头西侧的浮台上常聚集着数百头加州海狮，它们在 1989 年地震后不久开始在这里栖息，成了 39 号码头最受欢迎的“居民”。",
       en:"The pier's two-level Venetian-style carousel is a favorite photo spot. On floating docks along the west side, hundreds of California sea lions often gather; they began arriving soon after the 1989 earthquake and have become the pier's most popular residents."}},
  ghirardelli: {k:{zh:"老工厂改造商业区", en:"Converted factory complex"}, y:"1964",
    d:{zh:"吉尔德利广场原是吉尔德利巧克力公司的工厂，红砖厂房和钟楼俯瞰着水上公园。1960 年代工厂迁走后，这里被改造为商店和餐厅，是美国最早把旧工业建筑改作他用的项目之一。楼顶的大型灯光招牌在海湾上远远可见。",
       en:"Ghirardelli Square was once the factory of the Ghirardelli Chocolate Company, its red brick buildings and clock tower overlooking Aquatic Park. After the factory moved out in the 1960s, it was turned into shops and restaurants, one of the first US projects to give old industrial buildings a new use this way. Its big lit sign can be seen across the water."}},
  sfhyde: {k:{zh:"历史船只码头", en:"Historic ships pier"},
    d:{zh:"海德街码头属于旧金山海事国家历史公园，停泊着一批可以登船参观的历史船只，包括 1886 年的三桅横帆船“巴尔克卢瑟号”和 1890 年的蒸汽渡轮“尤里卡号”。它们讲述了旧金山作为港口城市的航海往事。",
       en:"Hyde Street Pier is part of San Francisco Maritime National Historical Park, where visitors can board a fleet of historic ships. They include the square-rigged Balclutha of 1886 and the steam ferry Eureka of 1890. Together they tell the story of San Francisco's life as a port city."}},
  sfhyde2: {k:{zh:"海事博物馆", en:"Maritime museum"}, y:"1939",
    d:{zh:"水上公园浴场是一座 1939 年由公共事业振兴署（WPA）建造的流线型现代风格建筑，外形像一艘停在岸边的白色邮轮。它现在是海事博物馆，室内还保留着当年的海洋主题壁画。",
       en:"The Aquatic Park Bathhouse, built in 1939 by the Works Progress Administration, is a Streamline Moderne building shaped like a white ocean liner on the shore. It now houses the Maritime Museum and still keeps its original sea-themed murals."}},
  sfcliffhouse: {k:{zh:"海崖建筑", en:"Clifftop building"}, y:"1909",
    d:{zh:"悬崖屋位于城市西端的海边峭壁上，面向太平洋和海豹岩。这里先后建过几座悬崖屋，现在的这座 1909 年建成，长期作为餐厅，也是看日落的好地方。",
       en:"The Cliff House sits on the cliffs at the western edge of the city, looking out over the Pacific and Seal Rocks. Several buildings have stood here; the current one was built in 1909 and served for many years as a restaurant and a favorite place to watch the sunset."}},
  sfcliffhouse2: {k:{zh:"遗址", en:"Ruins"}, y:"1896",
    d:{zh:"苏特罗浴场由富商阿道夫·苏特罗于 1896 年开设，曾是世界上最大的室内游泳场馆，玻璃屋顶下有七个海水泳池。后来经营衰落，1966 年在拆除期间被大火烧毁；如今海边只剩下混凝土基础和水池遗迹，可以沿步道参观。",
       en:"Adolph Sutro opened the Sutro Baths in 1896 as the world's largest indoor swimming establishment, with seven seawater pools under a glass roof. After years of decline the building burned in 1966 while being demolished. Today only the concrete foundations and pools remain by the sea, reached by a walking trail."}},

  /* ---------------- Golden Gate Park ---------------- */
  sfacademy: {k:{zh:"科学博物馆", en:"Science museum"}, y:"2008", a:{zh:"伦佐·皮亚诺", en:"Renzo Piano"},
    d:{zh:"加州科学院创立于 1853 年，2008 年在原址启用由伦佐·皮亚诺设计的新馆。起伏的“活屋顶”上种着约 170 万株本地植物，屋顶下的两个圆顶分别是天文馆和热带雨林馆，地下还有水族馆，把自然历史博物馆、水族馆和天文馆合在了一起。",
       en:"Founded in 1853, the California Academy of Sciences reopened in 2008 in a new building by Renzo Piano. Its rolling living roof is planted with about 1.7 million native plants, and the domes beneath hold a planetarium and a rainforest. With an aquarium below, it combines a natural history museum, aquarium and planetarium under one roof."}},
  deyoung: {k:{zh:"美术馆", en:"Art museum"}, y:"2005", a:{zh:"赫尔佐格和德梅隆", en:"Herzog & de Meuron"},
    d:{zh:"笛洋美术馆创立于 1895 年，现在的馆舍 2005 年落成，由赫尔佐格和德梅隆设计。外墙是打了孔、带凹凸纹理的铜板，会随时间慢慢氧化变绿，与公园的树林融为一体；扭转的观景塔可以俯瞰金门公园和整座城市。",
       en:"The de Young Museum was founded in 1895, and its current building, designed by Herzog & de Meuron, opened in 2005. Its perforated, dimpled copper skin is slowly weathering to green to blend with the park's trees. A twisting tower offers views over Golden Gate Park and the city."}},
  sfbandshell: {k:{zh:"露天音乐台", en:"Bandshell"}, y:"1900", a:{zh:"里德兄弟", en:"Reid Brothers"},
    d:{zh:"斯普雷克尔斯音乐殿是金门公园音乐广场上的露天音乐台，1900 年由糖业大亨克劳斯·斯普雷克尔斯捐建。砂岩拱门两侧连着柱廊，至今在温暖的季节仍举办免费音乐会。",
       en:"The Spreckels Temple of Music is the open-air bandshell on the Music Concourse in Golden Gate Park, given to the city in 1900 by sugar magnate Claus Spreckels. Its sandstone arch is flanked by colonnades, and free concerts are still held here in the warmer months."}},
  sfteagarden: {k:{zh:"日式园林", en:"Japanese garden"}, y:"1894",
    d:{zh:"日本茶园原是 1894 年加州仲冬国际博览会的展区，是美国最古老的公共日式庭园。园中有五重塔、太鼓桥、石灯笼和锦鲤池。长期照料这座园子的萩原家族，常被认为让幸运饼干在美国流行开来。",
       en:"The Japanese Tea Garden began as an exhibit at the 1894 California Midwinter International Exposition and is the oldest public Japanese garden in the United States. It has a five-story pagoda, a drum bridge, stone lanterns and koi ponds. The Hagiwara family, who tended it for decades, is often credited with popularizing the fortune cookie."}},
  conservatory: {k:{zh:"植物温室", en:"Glasshouse"}, y:"1879",
    d:{zh:"花卉温室 1879 年开放，是金门公园最古老的建筑，也是北美现存最古老的木结构玻璃温室之一。白色的维多利亚式穹顶下种着来自世界各地的热带植物，其中有大量珍稀兰花。",
       en:"Opened in 1879, the Conservatory of Flowers is the oldest building in Golden Gate Park and one of the oldest wood-and-glass conservatories in North America. Under its white Victorian dome grow tropical plants from around the world, including many rare orchids."}},
  sfwindmill: {k:{zh:"风车", en:"Windmill"}, y:"1903",
    d:{zh:"荷兰风车位于金门公园西北角，靠近海洋海滩，1903 年建成。当年它把地下水抽上来浇灌公园，帮助把原本的沙丘变成绿地。风车脚下的威廉明娜女王郁金香花园每到春天开满郁金香。",
       en:"The Dutch Windmill stands at the northwest corner of Golden Gate Park near Ocean Beach, built in 1903. It once pumped groundwater to irrigate the park, helping turn sand dunes into green land. In spring the Queen Wilhelmina Tulip Garden at its foot is full of tulips."}},
  sfwindmill2: {k:{zh:"风车", en:"Windmill"}, y:"1908",
    d:{zh:"墨菲风车位于金门公园西南角，1908 年建成，当时是世界上最大的风车之一，和北边的荷兰风车一起为公园抽水灌溉。它曾荒废多年，经修复后重新装上了风车叶片。",
       en:"Murphy Windmill, at the southwest corner of Golden Gate Park, was completed in 1908 and was once among the largest windmills in the world. Together with the Dutch Windmill to the north, it pumped water for the park. After decades of neglect it has been restored and its sails put back."}},

  /* ---------------- sites (campuses, airport) ---------------- */
  "site:sfoairport": {k:{zh:"国际机场", en:"International airport"}, y:"1927",
    d:{zh:"旧金山国际机场 1927 年以“米尔斯机场”之名开放，位于市区以南约 20 公里的海湾边。四条跑道两两交叉、伸向海湾，这里是湾区最繁忙的机场，也是通往亚洲和太平洋地区的重要门户；2000 年启用的国际航站楼由 SOM 设计。",
       en:"San Francisco International Airport opened in 1927 as Mills Field, on the bay shore about 20 km south of the city. Its four runways cross in two pairs and reach out into the bay. It is the Bay Area's busiest airport and a major gateway to Asia and the Pacific; the International Terminal, designed by SOM, opened in 2000."}},
  "site:applepark": {k:{zh:"企业园区", en:"Corporate campus"}, y:"2017", a:{zh:"福斯特建筑事务所", en:"Foster + Partners"},
    d:{zh:"苹果园区 2017 年启用，主体是福斯特建筑事务所设计的一座环形办公楼，周长约 1.6 公里，外墙用的是弧形玻璃。环形楼中间是种着果树和草地的庭院，屋顶铺满太阳能板；园区里还有以史蒂夫·乔布斯命名的剧院。",
       en:"Apple Park opened in 2017. Its centerpiece is a ring-shaped office building by Foster + Partners, about 1.6 km around and wrapped in curved glass. Inside the ring is a landscaped courtyard with orchards and meadows, the roof is covered with solar panels, and the campus also has the Steve Jobs Theater."}},
  "site:googleplex": {k:{zh:"企业园区", en:"Corporate campus"},
    d:{zh:"谷歌总部园区位于山景城的海湾边，核心建筑原是硅谷图形公司（SGI）的园区，谷歌在 2000 年代初搬进来后逐步扩展。园区以开阔的草坪、彩色的共享自行车和众多员工餐厅为人熟知。",
       en:"The Googleplex is Google's headquarters by the bay in Mountain View. Its core buildings were originally the campus of Silicon Graphics; Google moved in during the early 2000s and expanded from there. The campus is known for its open lawns, colorful shared bikes and many cafés."}},
  "site:googlebayview": {k:{zh:"企业园区", en:"Corporate campus"}, y:"2022", a:{zh:"BIG、赫斯维克工作室", en:"BIG, Heatherwick Studio"},
    d:{zh:"谷歌湾景园区 2022 年启用，由 BIG 和赫斯维克工作室设计，几座大楼罩在起伏的帐篷状屋顶下。屋顶铺着鳞片般交叠的“龙鳞”太阳能板，地下有大规模的地热系统；这是谷歌第一座自己设计建造的大型园区。",
       en:"Google Bay View opened in 2022, designed by BIG and Heatherwick Studio. Its buildings sit under rolling, tent-like roofs covered with overlapping “dragonscale” solar panels, and a large geothermal system lies underneath. It was the first major campus that Google designed and built itself."}},
  "site:stanforduniv": {k:{zh:"大学", en:"University"}, y:"1891",
    d:{zh:"斯坦福大学由利兰·斯坦福夫妇为纪念早逝的独子创办，1891 年开学。校园以砂岩拱廊、红瓦屋顶的主四方院为中心，规划时有弗雷德里克·劳·奥姆斯特德参与，胡佛塔和纪念教堂是其中的地标。它的发展与硅谷的兴起密切相关。",
       en:"Stanford University was founded by Leland and Jane Stanford in memory of their only son, and opened in 1891. The campus centers on the Main Quad of sandstone arcades and red-tile roofs, planned with Frederick Law Olmsted, with Hoover Tower and Memorial Church as landmarks. Its history is closely tied to the rise of Silicon Valley."}},
  "site:ucberkeley": {k:{zh:"大学", en:"University"}, y:"1868",
    d:{zh:"加州大学伯克利分校创建于 1868 年，是加州大学系统中最早的校区，1873 年迁到伯克利现址。校园中央的萨瑟塔（钟楼）高约 94 米，由约翰·盖伦·霍华德设计，登顶可眺望整个海湾。伯克利以众多诺贝尔奖得主和 1960 年代的言论自由运动闻名。",
       en:"Founded in 1868, the University of California, Berkeley is the oldest campus of the UC system and moved to its Berkeley site in 1873. At its center stands Sather Tower, the Campanile, about 94 m tall and designed by John Galen Howard, with views across the bay. Berkeley is known for its many Nobel laureates and the 1960s Free Speech Movement."}}
});
